import{_ as e,o,c as d,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Documents Module — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Documents Module — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/documents-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Documents Module — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/documents-production-readiness"}]]},"headers":[],"relativePath":"deployment/documents-production-readiness.md","filePath":"deployment/documents-production-readiness.md","lastUpdated":1787698014000}'),a={name:"deployment/documents-production-readiness.md"};function s(n,t,i,c,l,g){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="documents-module-—-production-readiness-audit" tabindex="-1">Documents Module — Production Readiness Audit <a class="header-anchor" href="#documents-module-—-production-readiness-audit" aria-label="Permalink to &quot;Documents Module — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-08-17</td></tr><tr><td><strong>Re-verified</strong></td><td>2026-08-17 (full open-finding remediation → <strong>1.0.1</strong>)</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> after migrate + uploads disk confirmation + Storage-first smoke</td></tr><tr><td><strong>Scope</strong></td><td>Free Marketplace opt-in <code>documents</code> <strong>1.0.1</strong> (hard dependency on <code>storage</code>)</td></tr><tr><td><strong>Branch</strong></td><td><code>feature/documents-module-mvp-b5f1</code></td></tr><tr><td><strong>Companion</strong></td><td><a href="./documents">Documents ops</a> · <a href="/developer-guide/documents">Developer</a> · <a href="/user-guide/documents">User</a> · <a href="/api/tenant-v1-documents">API</a></td></tr></tbody></table><p><strong>PRs:</strong> Backend <a href="https://github.com/DiligentCreators/SaaS-Backend/pull/117" target="_blank" rel="noreferrer">#117</a> · Frontend <a href="https://github.com/DiligentCreators/SaaS-Frontend/pull/112" target="_blank" rel="noreferrer">#112</a> · Docs <a href="https://github.com/DiligentCreators/SaaS-Docs/pull/138" target="_blank" rel="noreferrer">#138</a> · Website <a href="https://github.com/DiligentCreators/SaaS-Website/pull/31" target="_blank" rel="noreferrer">#31</a></p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Documents is a <strong>flat internal file library</strong> (upload, flat categories, download, soft/force delete) on Storage quota. Catalog is <strong>free</strong>, <strong>not</strong> default-included, with a <strong>hard</strong> Storage dependency.</p><p>Audit open findings <strong>M2–M4</strong> and <strong>L2</strong> are remediated in <strong>1.0.1</strong>. Notes/timeline/assignment remain intentional MVP deferrals (<strong>L1</strong>).</p><p><strong>Go / No-Go:</strong> <strong>Go</strong> — engineering complete; ops completes migrate-only rollout, object-storage uploads disk, and staging smoke.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Catalog: <code>documents</code> / operations / <strong>1.0.1</strong> / free / not default</td><td><strong>Pass</strong></td></tr><tr><td>Hard dependency Documents → Storage</td><td><strong>Pass</strong></td></tr><tr><td>Permissions sync + default role maps</td><td><strong>Pass</strong> (<code>force.delete</code> owner-only — intentional)</td></tr><tr><td>Quota on create / replace / restore</td><td><strong>Pass</strong></td></tr><tr><td>Soft-deleted disk lifecycle + trash purge</td><td><strong>Pass</strong> (<code>TrashPurgeRegistry</code> + <code>forceDeleting</code> disk cleanup)</td></tr><tr><td>Force delete disk-before-DB</td><td><strong>Pass</strong> (<code>forceDeleting</code> hook)</td></tr><tr><td>Platform audit create/update/delete/restore/force</td><td><strong>Pass</strong></td></tr><tr><td>Multipart update via <code>POST /documents/{id}</code></td><td><strong>Pass</strong></td></tr><tr><td>Pest <code>DocumentTest</code></td><td><strong>Pass</strong></td></tr><tr><td>Playwright headed Documents</td><td><strong>Pass</strong> (prior 1.0.0 session; replace path still POST)</td></tr><tr><td>Docs + marketing free / available</td><td><strong>Pass</strong></td></tr><tr><td>Notes / timeline / assign / nested folders</td><td><strong>Accepted</strong> — deferred MVP (<strong>L1</strong>)</td></tr></tbody></table><hr><h2 id="remediation-log-audit-→-fix" tabindex="-1">Remediation log (audit → fix) <a class="header-anchor" href="#remediation-log-audit-→-fix" aria-label="Permalink to &quot;Remediation log (audit → fix)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Was</th><th>Fix</th></tr></thead><tbody><tr><td><strong>H1</strong></td><td>Restore could exceed Storage quota</td><td><code>assertCanStore</code> on restore + Pest</td></tr><tr><td><strong>M1</strong></td><td>No Pest for file replace</td><td>Multipart <code>POST /documents/{id}</code> Pest</td></tr><tr><td><strong>M2</strong></td><td>Soft-deleted objects linger forever on disk</td><td><code>Document</code> (+ category) in <code>TrashPurgeRegistry</code>; purge uses workspace <code>trash.retention_days</code></td></tr><tr><td><strong>M3</strong></td><td>DB force-delete before disk → orphan objects</td><td><code>Document::forceDeleting</code> deletes via <code>FileUploadService</code> before row removal (covers API + <code>trash:purge-expired</code>)</td></tr><tr><td><strong>M4</strong></td><td>No platform audit for restore / force delete</td><td><code>document_restored</code> + <code>document_force_deleted</code> (Help Desk–style <code>force</code> flag)</td></tr><tr><td><strong>L2</strong></td><td>True HTTP PUT multipart unreliable</td><td>Named <code>POST documents/{id}</code> twin (<code>documents.update.post</code>); SPA posts FormData without <code>_method</code></td></tr><tr><td><strong>D1</strong></td><td>No production-readiness page</td><td>This page</td></tr></tbody></table><h3 id="accepted-intentional" tabindex="-1">Accepted / intentional <a class="header-anchor" href="#accepted-intentional" aria-label="Permalink to &quot;Accepted / intentional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td><strong>L1</strong> notes / timeline / assignment</td><td>Deferred flat-library MVP</td></tr><tr><td><code>force.delete</code> not on admin defaults</td><td>Owner / custom grant (Assets / Vendors parity)</td></tr><tr><td>Soft-deleted <code>show</code> → not found</td><td>Trash list + restore / force remain</td></tr><tr><td>Concurrent soft over-quota</td><td>Check-then-write; Storage class residual</td></tr><tr><td>Local uploads disk in non-prod</td><td>Production must use object storage</td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>Tenant isolation</td><td>Pass</td></tr><tr><td>Module gate + Spatie permissions + policies</td><td>Pass</td></tr><tr><td>File validation max 50 MB + mime allow-list</td><td>Pass</td></tr><tr><td>Download authz</td><td>Pass</td></tr><tr><td>Path / disk not in API resources</td><td>Pass</td></tr><tr><td>Trash purge removes objects</td><td>Pass</td></tr></tbody></table><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>php artisan test --compact tests/Feature/Tenant/Document/DocumentTest.php</code></td><td><strong>16 passed</strong> (81 assertions)</td><td>create/list, categories, CRUD trash, download, quota, restore-over-quota, POST replace, audit restore/force, trash purge + disk, registry</td></tr><tr><td><code>npm run test:e2e:documents:headed</code></td><td><strong>Pass</strong> (~47s prior)</td><td>Re-run on staging after 1.0.1</td></tr></tbody></table><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li>Deploy <strong>Backend</strong> (through <code>2026_08_17_100005</code> catalog bump to <strong>1.0.1</strong>)</li><li><code>php artisan migrate --force</code></li><li>Confirm <code>FILESYSTEM_UPLOADS_DISK</code> + object-storage credentials</li><li>Confirm scheduler runs <code>trash:purge-expired</code> daily (<code>onOneServer</code>)</li><li>Deploy <strong>Frontend</strong> (multipart update POST)</li><li>Deploy <strong>Docs</strong> / marketing</li><li>Staging smoke → production</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs → Website</strong>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations through Documents <code>100005</code> applied</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Catalog <code>documents</code> version <strong>1.0.1</strong>, free, not default</td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td><code>module_dependencies</code> Documents → Storage</td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Uploads disk is object storage</td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td><code>trash:purge-expired</code> scheduled</td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Pest Document suite green in CI</td><td>Eng</td><td>☑</td></tr><tr><td>7</td><td>Headed Playwright Documents on staging</td><td>QA</td><td>☐</td></tr><tr><td>8</td><td>Storage entitled before Documents install</td><td>QA</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Install Documents without Storage → blocked</li><li>Install Storage → Documents → upload / categorize / download</li><li>Soft delete → used bytes drop → restore → bytes return</li><li>Soft-delete → fill quota → restore blocked (<code>STORAGE_QUOTA_EXCEEDED</code>)</li><li>Soft-delete → set retention 30 → age <code>deleted_at</code> → <code>trash:purge-expired</code> removes DB row <strong>and</strong> object</li><li>Force delete removes object; category delete blocked while docs reference it</li><li>Multipart replace via <code>POST /documents/{id}</code> (no <code>_method</code> required)</li><li>Platform audit: create, soft delete, restore, force delete</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><ul><li>Forward-fix only — <strong>do not</strong> <code>migrate:rollback</code></li><li>Feature rollback = revert SPA/API deploys; catalog entitlements may remain</li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Engineering</td><td></td><td></td><td>☐ Prod Go</td></tr><tr><td>Ops (migrate + uploads disk + scheduler)</td><td></td><td></td><td>☐</td></tr><tr><td>Product</td><td></td><td></td><td>☐</td></tr></tbody></table><p><strong>Current decision (2026-08-17):</strong> <strong>Go</strong> — ship after migrate-only rollout, object-storage confirmation, and staging smoke.</p>',37)])])}const m=e(a,[["render",s]]);export{h as __pageData,m as default};
